export interface RequestOptions { method?: 'GET' | 'POST' | 'PUT' | 'DELETE'; data?: unknown; token?: string }
export interface TransportInput { url: string; method: NonNullable<RequestOptions['method']>; data?: unknown; header: Record<string, string>; timeout: number }
export type Transport = (input: TransportInput) => Promise<{ statusCode: number; data: unknown }>
export function createRequest(transport: Transport, baseUrl: string) {
  return async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
    if (!baseUrl) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
    const response = await transport({ url: `${baseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`, method: options.method ?? 'GET', data: options.data, header: { 'Content-Type': 'application/json', ...(options.token ? { Authorization: `Bearer ${options.token}` } : {}) }, timeout: 15000 })
    if (response.statusCode < 200 || response.statusCode >= 300) throw new Error(`请求失败（HTTP ${response.statusCode}）`)
    return response.data as T
  }
}
